interface HTTPWiringHandler<I, O> {
    input: I;
    output: O;
}

export type HTTPWiringsMap = {
  readonly '/api/auth{/*splat}': {
    readonly GET: HTTPWiringHandler<null, AuthHandlerOutput>,
    readonly POST: HTTPWiringHandler<null, AuthHandlerOutput>,
  },
  readonly '/workflow-run/:runId/stream': {
    readonly GET: HTTPWiringHandler<FlattenedRPCMap['console:streamWorkflowRun']['input'], FlattenedRPCMap['console:streamWorkflowRun']['output']>,
  },
  readonly '/scenario-run/:runId/artifact': {
    readonly GET: HTTPWiringHandler<FlattenedRPCMap['console:getScenarioArtifact']['input'], FlattenedRPCMap['console:getScenarioArtifact']['output']>,
  },
  readonly '/events/:topic': {
    readonly GET: HTTPWiringHandler<RealtimeEventStreamInput, null>,
  },
  readonly '/workflow/:workflowName/status/:runId': {
    readonly GET: HTTPWiringHandler<WorkflowStatusCheckerInput, WorkflowRunStatus>,
  },
  readonly '/workflow/:workflowName/status/:runId/stream': {
    readonly GET: HTTPWiringHandler<WorkflowStatusStreamInput, null>,
  },
  readonly '/workflow/:workflowName/status/:runId/stream/full': {
    readonly GET: HTTPWiringHandler<WorkflowStatusStreamFullInput, null>,
  },
  readonly '/categories': {
    readonly GET: HTTPWiringHandler<null, ListCategoriesOutput>,
    readonly POST: HTTPWiringHandler<CreateCategoryInput, CreateCategoryOutput>,
  },
  readonly '/items': {
    readonly GET: HTTPWiringHandler<ListItemsInput, ListItemsOutput>,
    readonly POST: HTTPWiringHandler<CreateItemInput, CreateItemOutput>,
  },
  readonly '/items/:itemId': {
    readonly GET: HTTPWiringHandler<GetItemInput, GetItemOutput>,
    readonly PATCH: HTTPWiringHandler<UpdateItemInput, null>,
  },
  readonly '/profile': {
    readonly GET: HTTPWiringHandler<null, GetProfileOutput>,
  },
  readonly '/basket': {
    readonly GET: HTTPWiringHandler<GetBasketInput, GetBasketOutput>,
  },
  readonly '/orders': {
    readonly GET: HTTPWiringHandler<ListOrdersInput, ListOrdersOutput>,
    readonly POST: HTTPWiringHandler<CreateOrderInput, CreateOrderOutput>,
  },
  readonly '/orders/:orderId': {
    readonly GET: HTTPWiringHandler<GetOrderInput, GetOrderOutput>,
    readonly DELETE: HTTPWiringHandler<DeleteOrderInput, null>,
  },
  readonly '/rpc/agent/:agentName': {
    readonly POST: HTTPWiringHandler<AgentCallerInput, AgentCallerOutput>,
  },
  readonly '/rpc/agent/:agentName/stream': {
    readonly POST: HTTPWiringHandler<AgentStreamCallerInput, null>,
  },
  readonly '/rpc/agent/:agentName/approve': {
    readonly POST: HTTPWiringHandler<AgentApproveCallerInput, null>,
  },
  readonly '/rpc/agent/:agentName/resume': {
    readonly POST: HTTPWiringHandler<AgentResumeCallerInput, null>,
  },
  readonly '/rpc/:rpcName': {
    readonly POST: HTTPWiringHandler<RpcCallerInput, null>,
  },
  readonly '/workflow/:workflowName/start': {
    readonly POST: HTTPWiringHandler<WorkflowStarterInput, WorkflowStarterOutput>,
  },
  readonly '/workflow/:workflowName/approve/:runId': {
    readonly POST: HTTPWiringHandler<WorkflowApproverInput, WorkflowApproverOutput>,
  },
  readonly '/workflow/:workflowName/run': {
    readonly POST: HTTPWiringHandler<WorkflowRunnerInput, null>,
  },
  readonly '/analytics': {
    readonly POST: HTTPWiringHandler<RecordAnalyticsEventsInput, RecordAnalyticsEventsOutput>,
  },
  readonly '/checkout': {
    readonly POST: HTTPWiringHandler<StartCheckoutInput, StartCheckoutOutput>,
  },
  readonly '/orders/:orderId/refund': {
    readonly POST: HTTPWiringHandler<StartRefundInput, StartRefundOutput>,
  },
  readonly '/agents/shop': {
    readonly POST: HTTPWiringHandler<AgentInput, HttpPostAgentsShopOutput>,
  },
  readonly '/agents/shop/stream': {
    readonly POST: HTTPWiringHandler<HttpPostAgentsShopStreamInput, null>,
  },
  readonly '/agents/ops/approve': {
    readonly POST: HTTPWiringHandler<HttpPostAgentsOpsApproveInput, unknown>,
  },
  readonly '/agents/ops/resume': {
    readonly POST: HTTPWiringHandler<HttpPostAgentsOpsResumeInput, null>,
  },
  readonly '/agents/ops': {
    readonly POST: HTTPWiringHandler<AgentInput, HttpPostAgentsOpsOutput>,
  },
  readonly '/agents/checkout': {
    readonly POST: HTTPWiringHandler<AgentInput, HttpPostAgentsCheckoutOutput>,
  },
  readonly '/basket/items': {
    readonly POST: HTTPWiringHandler<AddToBasketInput, null>,
  },
  readonly '/orders/:orderId/cancel': {
    readonly POST: HTTPWiringHandler<CancelOrderInput, null>,
  },
  readonly '/exports': {
    readonly POST: HTTPWiringHandler<null, StartExportOutput>,
  },
  readonly '/reports/conditional': {
    readonly POST: HTTPWiringHandler<null, null>,
  },
  readonly '/webhooks/stripe': {
    readonly POST: HTTPWiringHandler<FlattenedRPCMap['stripe:stripeWebhookHandler']['input'], FlattenedRPCMap['stripe:stripeWebhookHandler']['output']>,
  },
  readonly '/basket/items/:itemId': {
    readonly DELETE: HTTPWiringHandler<RemoveFromBasketInput, null>,
  },
};

export type HTTPWiringHandlerOf<HTTPWiring extends keyof HTTPWiringsMap, Method extends keyof HTTPWiringsMap[HTTPWiring]> =
    HTTPWiringsMap[HTTPWiring][Method] extends { input: infer I; output: infer O }
        ? HTTPWiringHandler<I, O>
        : never;

export type HTTPWiringsWithMethod<Method extends string> = {
  [HTTPWiring in keyof HTTPWiringsMap]: Method extends keyof HTTPWiringsMap[HTTPWiring] ? HTTPWiring : never;
}[keyof HTTPWiringsMap];
  